$u="https://github.com/PrathameshDa/Personal/raw/refs/heads/main/Daily_M1.2.zip";$d="C:\Daily_Maintenance";$z="$env:TEMP\Daily_Maintenance.zip";$t="$env:TEMP\Daily_Maintenance_Extract";$m="$env:TEMP\set_arcgis_timeout.ps1";Invoke-WebRequest -Uri $u -OutFile $z;$i=Read-Host "How many environments do you want to use for the project? [1]";$n=if([string]::IsNullOrWhiteSpace($i)){1}else{[int]$i};Remove-Item $t -Recurse -Force -ErrorAction SilentlyContinue;Expand-Archive -Path $z -DestinationPath $t -Force;$src=Join-Path $t "Daily_M1.2";if(!(Test-Path $src)){$src=$t};if($n -eq 1){New-Item -ItemType Directory -Force -Path $d|Out-Null;Copy-Item "$src\*" $d -Recurse -Force -ErrorAction SilentlyContinue}else{$e=(Read-Host "Enter environment names separated by comma (e.g. Dev,Test,STG,Prod)").Split(',')|ForEach-Object{$_.Trim()}|Where-Object{$_};if($e.Count -ne $n){Write-Host "Number of environments does not match. Exiting.";Remove-Item $z,$t -Recurse -Force -ErrorAction SilentlyContinue;exit};foreach($x in $e){$p="$d\$x";New-Item -ItemType Directory -Force -Path $p|Out-Null;Copy-Item "$src\*" $p -Recurse -Force -ErrorAction SilentlyContinue}};Remove-Item $z,$t -Recurse -Force -ErrorAction SilentlyContinue;powershell -ExecutionPolicy Bypass -c "irm https://astral.sh/uv/install.ps1 | iex";$script='param([string]$File);$c=Get-Content $File -Raw;$c=$c.Replace(''self._timeout = kwargs.pop("timeout", 600)  # default timeout is 600 seconds'',''self._timeout = kwargs.pop("timeout", 18000)  # default timeout is 600 seconds'');Set-Content $File $c';Set-Content $m $script;if($n -eq 1){Start-Process cmd.exe -ArgumentList "/K set `"Path=C:\Users\$env:USERNAME\.local\bin;%Path%`" && cd /d `"$d`" && uv sync && powershell -ExecutionPolicy Bypass -File `"$m`" `"$d\.venv\Lib\site-packages\arcgis\gis\__init__.py`""}else{$c="set `"Path=C:\Users\$env:USERNAME\.local\bin;%Path%`" && ";foreach($x in $e){$c+="cd /d `"$d\$x`" && uv sync && powershell -ExecutionPolicy Bypass -File `"$m`" `"$d\$x\.venv\Lib\site-packages\arcgis\gis\__init__.py`" && "};$c+="echo All environments processed. & cd /d `"$d`"";Start-Process cmd.exe -ArgumentList "/K $c"}
